from pathlib import Path

ROOT=Path('projects/arcane-circle')
JAVA=ROOT/'src/main/java/kr/moonseungjun/arcanecircle'


def text(path): return path.read_text(encoding='utf-8')
def write(path,value): path.write_text(value,encoding='utf-8')
def once(value,old,new,label):
    count=value.count(old)
    if count!=1: raise SystemExit(f'{label}: expected one anchor, got {count}')
    return value.replace(old,new,1)

